20	// secretPattern matches high-entropy strings that may be secrets.
21	// Note: / is excluded to prevent matching entire file paths as single tokens.
22	// Base64 and JWT tokens are still caught via high-entropy segments between slashes.
23	var secretPattern = regexp.MustCompile(`[A-Za-z0-9+_=-]{10,}`)
24	
25	// credentialedURIPattern matches URLs that embed userinfo with a password, such
26	// as REDACTED or REDACTED These often have
27	// moderate entropy and are not reliably covered by vendor-specific scanners.
28	var credentialedURIPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9+.-]{1,31}://[^\s/?#@"'` + "`" + `<>:]*:[^\s/?#@"'` + "`" + `<>]+@[^\s"'` + "`" + `<>]+`)
29	
30	// dbPasswordKeyShape matches a DB-prefixed credential key (vendor prefix +
31	// optional `_word`/`-word` segments + `password`/`passwd`/`pwd`). Used to
32	// compose both the env-var assignment regex and the JSON-key regex so the
33	// vendor list stays in one place.
34	const dbPasswordKeyShape = `(?:db|database|pg|postgres|postgresql|mysql|mariadb|redis|mongo|mongodb|sqlserver|mssql|jdbc)(?:[_-]+[a-z0-9]+)*[_-]*(?:password|passwd|pwd)` //nolint:gosec // regex literal, not a credential
35	
36	var (
37		jdbcPattern          = regexp.MustCompile(`(?i)\bjdbc:[^\s"'<>` + "`" + `]+`)
38		databaseURLPattern   = regexp.MustCompile(`(?i)\b(?:postgres(?:ql)?|mysql|mariadb|mongodb(?:\+srv)?|redis)://[^\s"'<>` + "`" + `]+`)
39		keywordDSNPattern    = regexp.MustCompile(`(?i)\b[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)(?:\s+[a-z_][a-z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s"']+)){2,}`)
40		semicolonConnPattern = regexp.MustCompile(`(?i)\b[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|"[^"]*"|'[^']*'|[^=;"'\s]+)(?:;[a-z][a-z0-9 _-]*=(?:\{[^}]*\}|"[^"]*"|'[^']*'|[^=;"'\s]+)){2,}`)
41		// credentialValuePattern requires the prefix to start at a non-alphanumeric
42		// boundary, so APP_DB_PASSWORD matches via the leading `_` but mydbpassword
43		// does not.
44		credentialValuePattern = regexp.MustCompile(`(?i)(?:^|[^A-Za-z0-9])(` + dbPasswordKeyShape + `)\s*=\s*("[^"]*"|'[^']*'|[^\s,;&]+)`)
45	
46		keywordHostPattern      = regexp.MustCompile(`(?i)(?:^|\s)host=`)
47		keywordUserPattern      = regexp.MustCompile(`(?i)(?:^|\s)user=`)
48		semicolonServerPattern  = regexp.MustCompile(`(?i)(?:^|;)\s*(?:server|data source|datasource|addr|address|network address)\s*=`)
49		semicolonUserPattern    = regexp.MustCompile(`(?i)(?:^|;)\s*(?:user id|userid|user|uid)\s*=`)
50		passwordAssignmentRegex = regexp.MustCompile(`(?i)(?:^|[?&;\s])(?:password|pwd)=("[^"]*"|'[^']*'|[^&;\s"']+)`)
51		// credentialJSONKeyRegex operates on output of normalizeCredentialJSONKey
52		// (already lowercased, `-`/` `/`.` → `_`), so the `(?i)` flag is unnecessary.
53		credentialJSONKeyRegex  = regexp.MustCompile(`^` + dbPasswordKeyShape + `$`)
54		genericPasswordKeyRegex = regexp.MustCompile(`(?i)^(?:password|passwd|pwd)$`)
55	)
