57	// entropyThreshold is the minimum Shannon entropy for a string to be considered
58	// a secret. 4.5 was chosen through trial and error: high enough to avoid false
59	// positives on common words and identifiers, low enough to catch typical API keys
60	// and tokens which tend to have entropy well above 5.0.
61	const entropyThreshold = 4.5
62	
63	// RedactedPlaceholder is the replacement text used for redacted secrets.
64	const RedactedPlaceholder = "REDACTED"
65	
66	// placeholderSecretValues lists lowercase values that should be treated as
67	// non-secrets when they appear as a credential value: prior redactions
68	// (REDACTED / [REDACTED] / <REDACTED>), common documentation placeholders,
69	// and obviously-non-real defaults. Values matched by shape (mask runs,
70	// `<…>` brackets, `${…}` shell expansion) are handled separately.
71	var placeholderSecretValues = func() map[string]struct{} {
72		lower := strings.ToLower(RedactedPlaceholder)
73		values := []string{
74			lower, "[" + lower + "]", "<" + lower + ">",
75			"changeme", "example", "placeholder",
76			"your_password", "your_db_password", "your_secret",
77			"secret_here",
78		}
79		out := make(map[string]struct{}, len(values))
80		for _, v := range values {
81			out[v] = struct{}{}
82		}
83		return out
84	}()
