114	var (
115		betterleaksDetector     *detect.Detector
116		betterleaksDetectorOnce sync.Once
117	)
118	
119	func getDetector() *detect.Detector {
120		betterleaksDetectorOnce.Do(func() {
121			d, err := detect.NewDetectorDefaultConfig()
122			if err != nil {
123				return
124			}
125			betterleaksDetector = d
126		})
127		return betterleaksDetector
128	}
