147	type connectionStringRule struct {
148		pattern   *regexp.Regexp
149		hasSecret func(string) bool
150	}
151	
152	var connectionStringRules = []connectionStringRule{
153		{pattern: jdbcPattern, hasSecret: hasJDBCPassword},
154		{pattern: databaseURLPattern, hasSecret: hasDatabaseURLSecret},
155		{pattern: keywordDSNPattern, hasSecret: hasKeywordDSNPassword},
156		{pattern: semicolonConnPattern, hasSecret: hasSemicolonConnectionPassword},
157	}
158	
159	// String replaces secrets and PII in s using layered detection:
160	//  1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
161	//  2. Pattern-based: betterleaks regex rules (260+ known secret formats)
162	//  3. Provider token prefixes: deterministic prefix rules for credential
163	//     formats betterleaks misses in isolation (e.g. Supabase sb_secret_)
164	//  4. Credentialed URIs: URLs containing userinfo passwords
165	//  5. Database connection strings: JDBC, keyword DSNs, and semicolon strings
166	//  6. User-defined custom rules: configured via ConfigureCustomRules
167	//  7. Bounded credential key/value pairs: DB_PASSWORD=...
168	//  8. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
169	//
170	// A string is redacted if ANY method flags it.
171	func String(s string) string {
172		return applyRegions(s, detectAllLayers(s))
173	}
174	
175	// detectAllLayers runs the eight always-on/opt-in regex-based redaction
176	// layers and returns their tagged regions. The OpenAI Privacy Filter
177	// (the final, network-backed layer) is NOT included — callers that want it
178	// append detectOPF spans to the result before passing to applyRegions. See
179	// StringWithPrivacyFilter for the augmented flow.
180	func detectAllLayers(s string) []taggedRegion {
181		var regions []taggedRegion
182	
183		// 1. Entropy-based detection (secrets — always on).
184		for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
185			start, end := loc[0], loc[1]
186	
187			// Don't consume characters that are part of JSON/string escape sequences.
188			// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
189			// (consuming the 'n' from '\n'), and after replacement the '\' would be
190			// followed by 'R' from "REDACTED", creating invalid escape '\R'.
191			// Only skip for known JSON escape letters to avoid trimming real secrets
192			// that happen to follow a literal backslash in decoded content.
193			if start > 0 && s[start-1] == '\\' {
194				switch s[start] {
195				case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
196					start++
197					if end-start < 10 {
198						continue
199					}
200				}
201			}
202	
203			if shannonEntropy(s[start:end]) > entropyThreshold {
204				regions = append(regions, taggedRegion{region: region{start, end}})
205			}
206		}
207	
208		// 2. Pattern-based detection via betterleaks (secrets — always on).
209		if d := getDetector(); d != nil {
210			for _, f := range d.DetectString(s) {
211				if f.Secret == "" {
212					continue
213				}
214				searchFrom := 0
215				for {
216					idx := strings.Index(s[searchFrom:], f.Secret)
217					if idx < 0 {
218						break
219					}
220					absIdx := searchFrom + idx
221					regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
222					searchFrom = absIdx + len(f.Secret)
223				}
224			}
225		}
226	
227		// 3. Provider-specific deterministic token prefixes (secrets — always on).
228		// Catches low-entropy credential formats (e.g. Supabase sb_secret_) that
229		// the entropy and betterleaks layers miss when captured in isolation.
230		regions = append(regions, detectProviderTokens(s)...)
231	
232		// 4. Credentialed URIs (secrets — always on).
233		for _, loc := range credentialedURIPattern.FindAllStringIndex(s, -1) {
234			regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
235		}
236	
237		// 5. Database and connection-string detection (secrets — always on).
238		regions = append(regions, detectConnectionStrings(s)...)
239	
240		// 6. User-defined custom rules (secrets — only runs when configured).
241		regions = append(regions, detectCustomRules(getCustomRulesConfig(), s)...)
242	
243		// 7. Bounded credential key/value detection (secrets — always on).
244		regions = append(regions, detectCredentialValues(s)...)
245	
246		// 8. PII detection (opt-in — only runs when configured).
247		regions = append(regions, detectPII(getPIIConfig(), s)...)
248	
249		return regions
250	}
251	
252	// applyRegions sorts, merges, and replaces the given regions in s, returning
253	// the redacted string. Returns s unchanged when regions is empty.
254	func applyRegions(s string, regions []taggedRegion) string {
255		if len(regions) == 0 {
256			return s
257		}
258	
259		sort.Slice(regions, func(i, j int) bool {
260			if regions[i].start != regions[j].start {
261				return regions[i].start < regions[j].start
262			}
263			if regions[i].end != regions[j].end {
264				return regions[i].end > regions[j].end // larger region first
265			}
266			return regions[i].label < regions[j].label // deterministic tie-break
267		})
268		merged := []taggedRegion{regions[0]}
269		for _, r := range regions[1:] {
270			last := &merged[len(merged)-1]
271			if r.start <= last.end {
272				if r.end > last.end {
273					last.end = r.end
274				}
275				// Keep the existing label (first/larger region wins)
276			} else {
277				merged = append(merged, r)
278			}
279		}
280	
281		var b strings.Builder
282		prev := 0
283		for _, r := range merged {
284			b.WriteString(s[prev:r.start])
285			b.WriteString(replacementToken(r.label))
286			prev = r.end
287		}
288		b.WriteString(s[prev:])
289		return b.String()
290	}
291	
292	func detectConnectionStrings(s string) []taggedRegion {
293		if !strings.ContainsRune(s, '=') {
294			return nil
295		}
296		var regions []taggedRegion
297		for _, rule := range connectionStringRules {
298			regions = append(regions, detectConnectionStringRule(s, rule)...)
299		}
300		return regions
301	}
302	
303	func detectConnectionStringRule(s string, rule connectionStringRule) []taggedRegion {
304		var regions []taggedRegion
305		for _, loc := range rule.pattern.FindAllStringIndex(s, -1) {
306			start, end := loc[0], trimConnectionStringEnd(s, loc[0], loc[1])
307			if start >= end {
308				continue
309			}
310			if rule.hasSecret(s[start:end]) {
311				regions = append(regions, taggedRegion{region: region{start, end}})
312			}
313		}
314		return regions
315	}
316	
317	func trimConnectionStringEnd(s string, start, end int) int {
318		for end > start {
319			switch s[end-1] {
320			case '.', ',', ';', ':', '!', '?', ')', ']':
321				end--
322			default:
323				return end
324			}
325		}
326		return end
327	}
328	
329	func hasJDBCPassword(candidate string) bool {
330		if !strings.HasPrefix(strings.ToLower(candidate), "jdbc:") {
331			return false
332		}
333		return hasNonPlaceholderPasswordAssignment(candidate)
334	}
335	
336	func hasDatabaseURLSecret(candidate string) bool {
337		u, err := url.Parse(candidate)
338		if err != nil || u.Scheme == "" || u.Host == "" {
339			return false
340		}
341		for key, values := range u.Query() {
342			if !isPasswordQueryKey(key) {
343				continue
344			}
345			for _, value := range values {
346				if hasNonPlaceholderPasswordValue(value) {
347					return true
348				}
349			}
350		}
351		return false
352	}
353	
354	func isPasswordQueryKey(key string) bool {
355		return strings.EqualFold(key, "password") || strings.EqualFold(key, "pwd")
356	}
357	
358	func hasKeywordDSNPassword(candidate string) bool {
359		return keywordHostPattern.MatchString(candidate) &&
360			keywordUserPattern.MatchString(candidate) &&
361			hasNonPlaceholderPasswordAssignment(candidate)
362	}
363	
364	func hasSemicolonConnectionPassword(candidate string) bool {
365		return semicolonServerPattern.MatchString(candidate) &&
366			semicolonUserPattern.MatchString(candidate) &&
367			hasNonPlaceholderPasswordAssignment(candidate)
368	}
369	
370	func detectCredentialValues(s string) []taggedRegion {
371		var regions []taggedRegion
372		for _, loc := range credentialValuePattern.FindAllStringSubmatchIndex(s, -1) {
373			if len(loc) < 6 || loc[4] < 0 || loc[5] < 0 {
374				continue
375			}
376			start, end := unquoteRange(s, loc[4], loc[5])
377			if hasNonPlaceholderPasswordValue(s[start:end]) {
378				regions = append(regions, taggedRegion{region: region{start, end}})
379			}
380		}
381		return regions
382	}
383	
384	func unquoteRange(s string, start, end int) (int, int) {
385		if end-start < 2 {
386			return start, end
387		}
388		first, last := s[start], s[end-1]
389		if (first == '"' && last == '"') || (first == '\'' && last == '\'') {
390			return start + 1, end - 1
391		}
392		return start, end
393	}
394	
395	func hasNonPlaceholderPasswordAssignment(candidate string) bool {
396		for _, loc := range passwordAssignmentRegex.FindAllStringSubmatchIndex(candidate, -1) {
397			if len(loc) >= 4 && loc[2] >= 0 && loc[3] >= 0 {
398				start, end := unquoteRange(candidate, loc[2], loc[3])
399				if hasNonPlaceholderPasswordValue(candidate[start:end]) {
400					return true
401				}
402			}
403		}
404		return false
405	}
406	
407	func hasNonPlaceholderPasswordValue(value string) bool {
408		return value != "" && !isPlaceholderSecretValue(value)
409	}
410	
411	func isPlaceholderSecretValue(value string) bool {
412		trimmed := strings.Trim(strings.TrimSpace(value), `"'`)
413		if trimmed == "" {
414			return true
415		}
416		if isBracketedPlaceholder(trimmed) {
417			return true
418		}
419		normalized := strings.ToLower(trimmed)
420		if strings.HasPrefix(normalized, "${") && strings.HasSuffix(normalized, "}") {
421			return true
422		}
423		if _, ok := placeholderSecretValues[normalized]; ok {
424			return true
425		}
426		return isRepeatedCharPlaceholder(normalized)
427	}
428	
429	// bracketedPlaceholderInteriorRE matches the inside of a "<…>" placeholder
430	// shape: lowercase letters joined by `-` or `_`. Digits, mixed case, and
431	// special chars are rejected so values like `<hunter2>` or `<RealPassword>`
432	// still fall through to redaction.
433	var bracketedPlaceholderInteriorRE = regexp.MustCompile(`^[a-z][a-z_-]*$`)
434	
435	// isBracketedPlaceholder reports whether s is a "<name>" doc placeholder
436	// (e.g. "<password>", "<your-db-password>"). The minimum total length of 5
437	// keeps this from firing on `<a>` / `<ab>`.
438	func isBracketedPlaceholder(s string) bool {
439		if len(s) < 5 || s[0] != '<' || s[len(s)-1] != '>' {
440			return false
441		}
442		return bracketedPlaceholderInteriorRE.MatchString(s[1 : len(s)-1])
443	}
444	
445	// isRepeatedCharPlaceholder reports whether s is a run of a single masking
446	// character commonly used to redact values in docs and screenshots, e.g.
447	// "***", "xxxx", "....", "----". The minimum length of 3 keeps single-char
448	// or 2-char values like `x` or `**` from being treated as masks.
449	func isRepeatedCharPlaceholder(s string) bool {
450		if len(s) < 3 {
451			return false
452		}
453		first := s[0]
454		switch first {
455		case '*', 'x', '.', '-':
456		default:
457			return false
458		}
459		for i := 1; i < len(s); i++ {
460			if s[i] != first {
461				return false
462			}
463		}
464		return true
465	}
466	
467	func isCredentialJSONSecretKey(key string, credentialContext bool) bool {
468		normalized := normalizeCredentialJSONKey(key)
469		if credentialJSONKeyRegex.MatchString(normalized) {
470			return true
471		}
472		return credentialContext && genericPasswordKeyRegex.MatchString(normalized)
473	}
474	
475	func isCredentialJSONObject(obj map[string]any) bool {
476		var hasHost, hasUser bool
477		for key := range obj {
478			switch normalizeCredentialJSONKey(key) {
479			case "host", "hostname", "server", "addr", "address", "datasource", "data_source":
480				hasHost = true
481			case "user", "username", "userid", "user_id", "uid":
482				hasUser = true
483			}
484			if hasHost && hasUser {
485				return true
486			}
487		}
488		return false
489	}
490	
491	func normalizeCredentialJSONKey(key string) string {
492		key = strings.ToLower(strings.TrimSpace(key))
493		key = strings.ReplaceAll(key, "-", "_")
494		key = strings.ReplaceAll(key, " ", "_")
495		// Flattened-config exporters (Spring, dotnet, Hashicorp Vault) emit dotted keys
496		// like "db.password" or "mysql.root.password"; treat them like underscored.
497		key = strings.ReplaceAll(key, ".", "_")
498		return key
499	}
