615	// StringWithPrivacyFilter augments String with the OpenAI Privacy Filter.
616	// Use only at condensation/export boundaries; per-turn writes must use
617	// String to avoid the OPF shell-out cost inside the agent loop.
618	func StringWithPrivacyFilter(ctx context.Context, s string) string {
619		regions := detectAllLayers(s)
620		regions = append(regions, detectOPF(ctx, getOPFConfig(), s)...)
621		return applyRegions(s, regions)
622	}
623	
624	// JSONLContentWithPrivacyFilter augments JSONLContent with the OpenAI
625	// Privacy Filter via batched inference. Walks the content twice: pass 1
626	// collects unique prose-shaped leaves into a single RedactBatch call;
627	// pass 2 applies the eight regex layers per leaf plus the cached OPF spans
628	// for that leaf. One OPF shell-out covers the whole transcript instead of
629	// one per leaf — without batching, a typical 500-leaf transcript would
630	// take many minutes per commit.
631	//
632	// Falls back to the plain JSONLContent flow when OPF is unconfigured, the
633	// breaker is tripped, no categories are enabled, or the batch call errors.
634	func JSONLContentWithPrivacyFilter(ctx context.Context, content string) (string, error) {
635		cfg := getOPFConfig()
636		if cfg == nil || !cfg.Enabled || cfg.runtime == nil || opfBreakerTripped.Load() {
637			return jsonlContentImpl(content, String)
638		}
639		cats := enabledCategories(cfg)
640		if len(cats) == 0 {
641			return jsonlContentImpl(content, String)
642		}
643	
644		// Pass 1: collect eligible (has-space, deduped) leaves. The collector
645		// closure returns identity so the JSONL walker doesn't mutate content.
646		seen := make(map[string]struct{})
647		var inputs []string
648		if _, err := jsonlContentImpl(content, func(v string) string {
649			if strings.ContainsRune(v, ' ') {
650				if _, ok := seen[v]; !ok {
651					seen[v] = struct{}{}
652					inputs = append(inputs, v)
653				}
654			}
655			return v
656		}); err != nil {
657			return "", err
658		}
659	
660		// Pass 2: single batched OPF call.
661		spansByInput := make(map[string][]Span, len(inputs))
662		if len(inputs) > 0 {
663			fmt.Fprintln(opfStderr, "→ OpenAI Privacy Filter: scanning transcript…")
664			start := time.Now()
665			batched, err := cfg.runtime.RedactBatch(ctx, inputs, cats)
666			if err != nil {
667				handleOPFFailure(ctx, cfg, err)
668				return jsonlContentImpl(content, String)
669			}
670			fmt.Fprintf(opfStderr, "✓ OpenAI Privacy Filter: done (%.1fs)\n", time.Since(start).Seconds())
671			// A short return means the runtime gave us fewer span slices than
672			// inputs — the tail leaves would receive zero OPF spans and the
673			// caller would proceed as if OPF had found nothing. That silently
674			// produces under-redacted output and is indistinguishable from a
675			// "no PII present" result. Treat as a runtime contract violation:
676			// trip the breaker so the pre-push rewrite's post-loop
677			// OPFBreakerTripped() check aborts before the Entire-OPF-Applied
678			// trailer can be attached to under-redacted commits. The production
679			// shell-out always returns len(inputs), so this only fires for a
680			// misbehaving custom runtime — but the cost of leaving it dormant
681			// is too high for a privacy contract.
682			if len(batched) != len(inputs) {
683				shortErr := fmt.Errorf("opf runtime returned %d span slices for %d inputs", len(batched), len(inputs))
684				handleOPFFailure(ctx, cfg, shortErr)
685				return jsonlContentImpl(content, String)
686			}
687			for i, in := range inputs {
688				spansByInput[in] = batched[i]
689			}
690		}
691	
692		// Pass 3: per-leaf regex layers + cached OPF spans.
693		return jsonlContentImpl(content, func(v string) string {
694			regions := detectAllLayers(v)
695			regions = append(regions, opfSpanRegions(v, spansByInput[v], cfg)...)
696			return applyRegions(v, regions)
697		})
698	}
