		t.Fatalf("goredact: %v", err)
	}
	return out.String()
}

// TestQualityMatrix prints a detection matrix; it never fails. Inspect output.
func TestQualityMatrix(t *testing.T) {
	balanced, err := goredact.New(goredact.Config{Profile: goredact.ProfileBalanced})
	if err != nil {
		t.Fatal(err)
	}
	deep, err := goredact.New(goredact.Config{Profile: goredact.ProfileDeep})
	if err != nil {
		t.Fatal(err)
	}

	check := func(s sample) (entireHit, balHit, deepHit bool) {
		er := redact.String(s.text)
		br := redactWithGoredact(t, balanced, s.text)
		dr := redactWithGoredact(t, deep, s.text)
		if s.secret != "" {
			return !strings.Contains(er, s.secret), !strings.Contains(br, s.secret), !strings.Contains(dr, s.secret)
		}
		// negatives: "hit" means anything was changed (over-redaction)
		return er != s.text, br != s.text, dr != s.text
	}

	fmt.Printf("\n%-30s %-8s %-12s %-8s\n", "POSITIVE (want redacted)", "entire", "gr-balanced", "gr-deep")
	var eP, bP, dP int
	for _, s := range positives {
		e, b, d := check(s)
		mark := func(ok bool) string {
			if ok {
				return "YES"
			}
			return "-- MISS"
		}
		if e {
			eP++
		}
		if b {
			bP++
		}
		if d {
			dP++
		}
		fmt.Printf("%-30s %-8s %-12s %-8s\n", s.name, mark(e), mark(b), mark(d))
	}
	fmt.Printf("%-30s %d/%d      %d/%d         %d/%d\n\n", "recall", eP, len(positives), bP, len(positives), dP, len(positives))

	fmt.Printf("%-30s %-8s %-12s %-8s\n", "NEGATIVE (want untouched)", "entire", "gr-balanced", "gr-deep")
	var eF, bF, dF int
	for _, s := range negatives {
		e, b, d := check(s)
		mark := func(fp bool) string {
			if fp {
				return "FALSE-POS"
			}
			return "clean"
		}
		if e {
			eF++
		}
		if b {
			bF++
		}
		if d {
			dF++
		}
		fmt.Printf("%-30s %-8s %-12s %-8s\n", s.name, mark(e), mark(b), mark(d))
	}
	fmt.Printf("%-30s %d/%d      %d/%d         %d/%d\n", "false positives", eF, len(negatives), bF, len(negatives), dF, len(negatives))
}

