// maybeWarnNarrowedScanners prints a one-line stderr note when betterleaks
// is disabled, once per effective scanner configuration. The marker lives
// on a gitignored path (same ignore treatment as settings.local.json) so
// it can never land committable. Best-effort: marker IO failures degrade
// to warning every run, never to silence.
func maybeWarnNarrowedScanners(ctx context.Context, s *settings.EntireSettings) {
	if s.BetterleaksEnabled() {
		return
	}
	fingerprint := fmt.Sprintf("betterleaks=%t goredact=%t\n", s.BetterleaksEnabled(), s.GoredactEnabled())
	markerRel := filepath.Join(paths.EntireDir, "logs", "scanner-notice")
	markerAbs, err := paths.AbsPath(ctx, markerRel)
	if err != nil {
		markerAbs = markerRel
	}
	if prev, rerr := os.ReadFile(markerAbs); rerr == nil && string(prev) == fingerprint {
		return
	}
	fmt.Fprintln(os.Stderr, "[entire] betterleaks scanning is disabled in .entire/settings.json; checkpoint redaction relies on the remaining layers"+goredactSuffix(s)+".")
	_ = os.MkdirAll(filepath.Dir(markerAbs), 0o755)
	_ = os.WriteFile(markerAbs, []byte(fingerprint), 0o644)
}

func goredactSuffix(s *settings.EntireSettings) string {
	if s.GoredactEnabled() {
		return " plus goredact"
	}
	return ""
}
