// initHookLogging configures redaction and initializes logging for hooks.
// Returns a cleanup function that should be deferred, and an error only
// for scanner-configuration failures, which must fail the hook.
// If Entire is not set up or disabled, returns a no-op.
func initHookLogging(ctx context.Context) (func(), error) {
	if !settings.IsSetUpAndEnabled(ctx) {
		return func() {}, nil
	}

	// Configure redaction FIRST: scanner selection must apply even when
	// logging fails to initialize below, because the hook proceeds to
	// write checkpoints either way. Scanner-specific failures fail the
	// hook; everything else is warn-and-default inside the call.
	if err := strategy.EnsureRedactionConfigured(); err != nil {
		return func() {}, err
	}

	logging.SetLogLevelGetter(GetLogLevel)
	sessionID := strategy.FindMostRecentSession(ctx)
	if err := logging.Init(ctx, sessionID); err != nil {
		return func() {}, nil
	}
	return logging.Close, nil
}
